.topic-legend { display: flex; align-items: center; gap: 6px; margin-top: 2px; font-size: 11px; font-weight: 600; color: var(--muted); }
.topic-legend i { width: 14px; height: 6px; border-radius: 3px; background: var(--yellow); }
.topic-bars b { text-align: right; font-size: 12px; }
.topic-bars .is-weak .bar i { background: var(--yellow); }
.exam-list { display: grid; }
.exam-list li { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; align-items: center; gap: 10px; padding: 7px 0; border-bottom: 1px solid var(--border); }
.exam-list li:last-child { border-bottom: 0; }
.exam-name { display: flex; flex-direction: column; font-weight: 600; font-size: 12px; }
.exam-name small { color: var(--muted); font-weight: 500; font-size: 11px; }
.exam-list b { font-size: 13px; }
.status { font-size: 10.5px; font-weight: 700; padding: 3px 6px; border-radius: 3px; white-space: nowrap; }
.status-pass { background: var(--sky); color: var(--navy); }
.status-fail { background: #fff; border: 1px solid var(--control); color: var(--navy); }
.week { display: grid; gap: 6px; margin-top: 2px; }
.week-label { font-size: 11px; color: var(--muted); font-weight: 600; }
.week-bars { display: grid; grid-template-columns: repeat(7, 1fr); align-items: end; gap: 6px; height: 54px; }
.week-bars i { display: block; height: var(--h); border-radius: 3px 3px 0 0; background: var(--sky-light); }
.week-bars i:nth-child(6) { background: var(--navy); }
.week-days { display: grid; grid-template-columns: repeat(7, 1fr); gap: 6px; text-align: center; font-size: 10px; color: var(--muted); }
@container dash (max-width: 760px) {
  .dash-side { display: none; }
  .dash-main { grid-column: 1 / -1; }
  .dash-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@container dash (max-width: 540px) {
  .dash-cols { grid-template-columns: minmax(0, 1fr); }
}
@container dash (max-width: 420px) {
  .dash-main { padding: 12px; }
  .dash-btn { display: none; }
  .kpi-val { font-size: 17px; }
}

/* ---------- Hero ---------- */
.hero { padding: 64px 0 72px; background: #fff; }
.hero-grid { display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr); align-items: center; gap: 56px; }
.hero-copy { display: flex; flex-direction: column; align-items: flex-start; }
.hero-copy .t-display { margin-bottom: 20px; }
.hero-copy .lead { margin-bottom: 24px; }
.checklist { display: grid; gap: 10px; margin-bottom: 32px; }
.checklist li { display: flex; align-items: flex-start; gap: 10px; font-weight: 500; }
.checklist .ic { width: 22px; height: 22px; margin-top: 1px; color: var(--navy); }
.checklist-sm { gap: 8px; margin-bottom: 0; }
.checklist-sm li { font-size: 15px; }
.checklist-sm .ic { width: 20px; height: 20px; }
.hero-trust { display: flex; flex-wrap: wrap; align-items: center; gap: 12px 28px; margin-top: 28px; padding-top: 24px; border-top: 1px solid var(--border); font-size: 14px; width: 100%; }
.trust-rating, .trust-item { display: inline-flex; align-items: center; gap: 10px; }
.hero-stage { position: relative; aspect-ratio: 1 / .92; border-radius: 12px; background: var(--panel); overflow: hidden; }
.hero-road { position: absolute; left: -10%; right: -10%; bottom: 14%; height: 17%; background: #d5dfe9; transform: rotate(-8deg); }
.hero-road::after { content: ""; position: absolute; left: 0; right: 0; top: 50%; height: 4px; margin-top: -2px; background: repeating-linear-gradient(90deg, #fff 0 34px, transparent 34px 60px); }
.hero-book { position: absolute; left: 7%; top: 8%; width: 62%; }
.hero-book .visual { aspect-ratio: 3 / 3.4; }
.hero-book .book { width: 76cqw; }
.hero-card { position: absolute; display: flex; flex-direction: column; gap: 6px; padding: 16px; background: #fff; border-radius: var(--r-lg); border: 1px solid var(--border); box-shadow: 0 20px 36px -24px rgba(11, 37, 69, .45); }
.hc-label { font-size: 12px; font-weight: 600; color: var(--muted); }
.hc-row { display: flex; align-items: center; gap: 12px; }
.hc-text { display: flex; flex-direction: column; font-size: 13px; line-height: 1.35; }
.hc-text strong { font-size: 15px; }
.hc-text span { color: var(--muted); }
.hero-card-exam { right: 6%; top: 12%; width: 44%; }
.hero-card-progress { right: 8%; bottom: 8%; width: 40%; }
.hc-big { font-size: 28px; font-weight: 800; line-height: 1; }
.hc-meta { font-size: 12px; color: var(--muted); }
.hero-card-topic { left: 6%; bottom: 7%; flex-direction: row; align-items: center; gap: 10px; padding: 12px 16px; }
.hc-ic { display: grid; place-items: center; width: 36px; height: 36px; border-radius: var(--r-md); background: var(--panel); }

/* ---------- USPs ---------- */
.usps { padding-bottom: 24px; }
.usp-grid { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 16px; }
.usp { display: flex; flex-direction: column; gap: 6px; padding: 20px 16px; background: var(--page); border-radius: var(--r-lg); }
.usp .ic { color: var(--navy); margin-bottom: 6px; }
.usp-title { font-size: 15px; font-weight: 700; line-height: 1.3; }
.usp p { font-size: 13.5px; line-height: 1.5; color: var(--muted); }

/* ---------- Categories ---------- */
.cat-grid { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 16px; }
.cat-card { display: flex; flex-direction: column; gap: 16px; padding: 24px 20px 20px; background: #fff; border: 1px solid var(--border); border-radius: var(--r-lg); transition: border-color .15s, transform .15s, background-color .15s; }
.cat-card:hover { border-color: var(--sky-light); transform: translateY(-2px); }
.cat-ic { display: grid; place-items: center; width: 72px; height: 72px; border-radius: var(--r-lg); background: var(--panel); color: var(--navy); }
.cat-body { display: flex; flex-direction: column; gap: 2px; }
.cat-title { font-size: 20px; font-weight: 700; line-height: 1.3; }
.cat-meta { display: inline-flex; align-items: center; gap: 4px; margin-top: auto; font-size: 14px; font-weight: 700; text-decoration: underline; text-decoration-color: var(--sky); text-decoration-thickness: 2px; text-underline-offset: 4px; }
.cat-card-accent { background: var(--navy); border-color: var(--navy); color: #fff; }
.cat-card-accent:hover { background: var(--navy-2); border-color: var(--navy-2); }
.cat-card-accent .cat-ic { background: rgba(255, 255, 255, .1); color: var(--sky-light); }
.cat-card-accent .muted { color: rgba(255, 255, 255, .78); }
.cat-card-accent .cat-meta { text-decoration-color: var(--yellow); }

/* ---------- Split (navy online teaser) ---------- */
.split { display: grid; grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr); align-items: center; gap: 56px; }
.split-copy .t-h2 { margin-bottom: 16px; }
.split-copy .lead { margin-bottom: 24px; }
.feature-list { display: grid; gap: 12px; margin-bottom: 32px; }
.feature-list li { display: flex; align-items: center; gap: 12px; font-weight: 500; }
.feature-list .ic { width: 22px; height: 22px; color: var(--sky-light); }

/* ---------- Steps ---------- */
.steps { display: grid; gap: 24px; counter-reset: step; }
.steps-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.steps-5 { grid-template-columns: repeat(5, minmax(0, 1fr)); }
.step { position: relative; display: flex; flex-direction: column; gap: 10px; }
.step::after { content: ""; position: absolute; top: 24px; left: 64px; right: -12px; height: 2px; background: repeating-linear-gradient(90deg, var(--sky-light) 0 8px, transparent 8px 14px); }
.step:last-child::after { display: none; }
.step-num { display: grid; place-items: center; width: 48px; height: 48px; border-radius: 50%; background: #fff; border: 2px solid var(--navy); font-size: 18px; font-weight: 800; color: var(--navy); margin-bottom: 8px; flex: none; }
.step .t-h3 { font-size: 19px; }
.step p { color: var(--muted); font-size: 15px; }
.steps-5 .t-h3 { font-size: 17px; }

/* ---------- Reviews ---------- */
.reviews-layout { display: grid; grid-template-columns: 320px minmax(0, 1fr); gap: 48px; align-items: start; }

